function overview(){return `<div class="hero"><div class="heroleft"><div class="heroicon">${icon('spark',22)}</div><div><h2>3 个项目，一次更有分量的采购</h2><p>发现 22AWG 红线存在同规格候选需求，合计 140,000 米。完成研发确认后，可发起集中议价。</p></div></div>${btn('查看聚合机会 '+icon('arrow',14),'go-demand')}</div><div class="stats">${stat('待聚合采购金额',money(totalSpend()),'元','11 月计划需求 · 含税含运费示例','coin')}${stat('可归并候选料号','3','个','对应 1 组规格 · 待研发确认','box')}${stat('候选供应商','4','家','线材 / 端子 / 塑料粒子示例','users')}${stat('待办采购任务',taskCount(),'项','行动与结果均可在演示中记录','task')}</div><div class="layout"><section class="card"><div class="cardhead"><div><h2>主材行情观察</h2><p>公开现货参考价 · 来源日期逐项展示</p></div><span class="badge">真实采集</span></div><div class="cardbody"><div id="market-overview">${window.MP?MP.renderOverview():'正在读取公开行情…'}</div><div class="chartfoot"><span>通用材料参考，非指定牌号报价</span><button class="link" data-page="cost">查看全部行情 ${icon('arrow',12)}</button></div></div></section><section class="card"><div class="cardhead"><div><h2>需要关注</h2><p>采购机会与协同事项</p></div><span class="badge">3 项</span></div><div class="cardbody"><div class="riskrow"><div class="riskicon green">${icon('layers',16)}</div><div><strong>同规格需求分散</strong><p>3 个料号 · 潜在聚合 14 万米</p></div><button class="link" data-page="demand">查看 ${icon('arrow',12)}</button></div><div class="riskrow"><div class="riskicon">${icon('shield',16)}</div><div><strong>供应商资质待续期</strong><p>远川电子 · 证书剩余 28 天</p></div><button class="link" data-page="suppliers">查看 ${icon('arrow',12)}</button></div><div class="riskrow"><div class="riskicon">${icon('box',16)}</div><div><strong>端子替代需要研发核验</strong><p>关键尺寸与认证范围待确认</p></div><button class="link" data-page="selection" data-cat="terminal">查看 ${icon('arrow',12)}</button></div></div></section></div><section class="card"><div class="cardhead"><div><h2>采购行动清单</h2><p>让每一条分析，都有下一步</p></div><button class="link" data-page="tasks">全部任务 ${icon('arrow',12)}</button></div><div class="tablewrap"><table><thead><tr><th>任务与机会</th><th>触发来源</th><th>负责人</th><th>期望完成</th><th>当前状态</th><th></th></tr></thead><tbody>${state.tasks.slice(0,4).map(t=>`<tr><td>${esc(t.title)}<small>${t.id}</small></td><td>${esc(t.category)}</td><td>${esc(t.owner)}</td><td>${esc(t.due)}</td><td>${taskStatus(t)}</td><td><button class="rowaction" data-task="${t.id}">查看任务 →</button></td></tr>`).join('')}</tbody></table></div></section>`}
function taskStatus(t){return status({todo:'待处理',progress:'进行中',done:'已完成'}[t.status],{todo:'orange',progress:'blue',done:''}[t.status])}
function field(label,id,type='text',value='',extra=''){return `<label class="field">${label}<input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function selectField(label,id,options,value){if(value&&!options.some(([v])=>v===value))options=[...options,[value,value]];return `<label class="field">${label}<select id="${id}">${options.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></label>`}
function filteredMaterials(){let f=state.filters;return materials.filter(m=>m.cat===state.category&&(!f.cert||m.cert===f.cert)&&(m.cat!=='wire'||((!f.awg||m.awg===f.awg)&&(!f.temp||m.temp>=Number(f.temp))))&&(m.cat!=='terminal'||!f.pitch||m.pitch===f.pitch)&&(m.cat!=='resin'||!f.grade||m.grade===f.grade));}
function selection(){let f=state.filters,rows=filteredMaterials();return `<section class="card"><div class="cardhead"><div><h2>描述需求，找到现有可用物料</h2><p>关键词规则匹配演示 · 支持线径、认证、耐温、针距、阻燃等级</p></div><span class="badge">9 条样例物料</span></div><div class="cardbody"><div class="searchbox">${icon('spark',18)}<input id="selection-query" aria-label="输入选型需求" placeholder="试试：需要 22AWG、UL 认证、105℃ 的红色电子线" value="${esc(state.query)}">${btn('匹配物料','match',true)}</div><div class="smalltext" style="margin-top:10px">示例：<button class="link" data-example="wire">22AWG UL 105℃ 红线</button> &nbsp; / &nbsp; <button class="link" data-example="terminal">UL 5.0mm 按压式端子</button> &nbsp; / &nbsp; <button class="link" data-example="resin">PC V-0 抗UV 粒子</button></div></div><div class="filterbar"><div class="tabs">${[['wire','电线'],['terminal','端子'],['resin','塑料粒子']].map(([v,l])=>`<button class="tab ${state.category===v?'active':''}" data-category="${v}">${l}</button>`).join('')}</div>${state.category==='wire'?selectField('线径','filter-awg',[['','全部线径'],['22AWG','22AWG'],['24AWG','24AWG']],f.awg)+selectField('最低耐温','filter-temp',[['','全部温度'],['80','80℃'],['105','105℃'],['150','150℃']],f.temp):state.category==='terminal'?selectField('针距','filter-pitch',[['','全部针距'],['5.0mm','5.0mm'],['7.5mm','7.5mm']],f.pitch):selectField('阻燃等级','filter-grade',[['','全部等级'],['V-0','V-0'],['V-2','V-2']],f.grade)}${selectField('认证','filter-cert',[['','全部认证'],['UL','UL'],['CQC','CQC']],f.cert)}<button class="link" data-action="clear-filters">清除筛选</button></div></section><div class="resultline">匹配到 <strong>${rows.length}</strong> 条供应资源<span>·</span>${state.query?'已提取结构化条件，请核对完整规格':'使用筛选条件缩小范围'}<span style="margin-left:auto">人民币 · 含税 13% · 含运费 · 2026-10-21 模拟报价</span></div><div class="threecol">${rows.map(m=>{let s=supplier(m.supplier);return `<article class="candidate ${state.selected===m.id?'selected':''}"><div style="display:flex;justify-content:space-between"><span class="badge">${m.id}</span>${status(state.reviewed.includes(m.id)?'演示中已确认':'研发待确认',state.reviewed.includes(m.id)?'':'orange')}</div><h3>${m.name}</h3><p>${m.description}</p><div class="chips"><span class="chip">${m.cert} 认证示例</span><span class="chip">${m.feature.split(' · ')[0]}</span><span class="chip">${m.lead} 天交期</span></div><div class="price">¥ ${money(m.price,2)} <small>/ ${m.unit}</small></div><div class="costrow"><span>供应商</span><strong>${s.name}</strong></div><div class="costrow"><span>品质 / 交付评分</span><strong>${s.quality} / ${s.delivery}</strong></div><div class="smalltext" style="margin:12px 0">匹配依据：${m.cat==='wire'?m.awg+' · '+m.cert+' · '+m.temp+'℃':m.cat==='terminal'?m.pitch+' · '+m.mount+' · '+m.cert:m.grade+' · '+m.uv+' · '+m.cert}</div>${btn('查看并确认选型 '+icon('arrow',13),'select-material',false,`data-id="${m.id}"`)}</article>`}).join('')||'<div class="empty">没有满足当前条件的物料，请调整筛选；系统不会以近似规格直接替代。</div>'}</div><div class="notice">${icon('shield',14)} 选型结果仅代表样例字段匹配。端子图纸、完整认证范围、额定参数与装配适配性均需研发核验；认证标签为虚构数据，不代表真实产品获证。</div>`}
function demandPage(){return `<div class="stats">${stat('计划需求量',money(totalQty()),'米','11 月需求快照 · 非实际采购量','layers')}${stat('候选归并料号','3','个',state.demandApproved?'演示中已完成研发确认':'关键规格相同 · 互换性待确认','box')}${stat('统一基准金额',money(totalSpend()),'元','140,000 米 × ¥0.46 / 米','coin')}${stat('议价触发门槛',money(state.threshold),'元',totalSpend()>=state.threshold?'已达到规则条件':'尚未达到规则条件','trend')}</div><section class="card"><div class="cardhead"><div><h2>22AWG UL1015 红线 · 跨项目需求包</h2><p>统一计量单位后聚合；原料号保留以便追溯</p></div>${status(state.demandApproved?'归并已确认':'研发归并待确认',state.demandApproved?'':'orange')}</div><div class="filterbar">${selectField('需求月份','demand-period',[['11','2026 年 11 月']],state.period)}${field('累计金额达到后触发议价（元）','demand-threshold','number',state.threshold,'min="1" step="1000"')}${btn('更新规则','update-threshold')}<span class="smalltext">规则范围：当前需求包，按统一基准金额判断</span></div><div class="tablewrap"><table><thead><tr><th>项目 / 需求来源</th><th>内部料号</th><th>物料规格</th><th>计划需求</th><th>需求日期</th><th>确认状态</th></tr></thead><tbody>${demand.map((d,i)=>`<tr><td><div class="materialcell"><div class="materialicon">${icon('box',16)}</div><div>${d.project}<small>模拟项目 · ${d.id}</small></div></div></td><td>${d.sku}</td><td>${d.spec}</td><td>${money(d.qty)} 米</td><td>${d.date}</td><td>${status(state.demandApproved||i===0?'研发已确认':'归并待确认',state.demandApproved||i===0?'':'orange')}</td></tr>`).join('')}</tbody></table></div><div class="summarystrip"><span>聚合合计 <strong>140,000 米</strong> &nbsp; / &nbsp; 统一基准 <strong>¥64,400</strong>（含税含运费）</span><div class="actions">${btn(state.demandApproved?'已完成演示确认':'研发确认归并','approve-demand',false,state.demandApproved?'disabled':'')}${btn('生成议价任务 '+icon('arrow',13),'create-demand-task',true)}</div></div></section><div class="twocol sectiongap"><section class="card"><div class="cardhead"><h2>从分散下单，到集中议价</h2>${icon('layers')}</div><div class="cardbody">${[['01','保留原始需求','三个项目、三个内部料号，需求来源和日期均可追溯。'],['02','研发确认可归并','当前样例只涉及同规格红线，需核验完整规格与替代边界。'],['03','聚合后触发行动','超过金额门槛并完成人工确认后，生成带基准量价的议价任务。']].map(([n,t,p])=>`<div class="helpstep"><span class="num">${n}</span><div><strong>${t}</strong><p>${p}</p></div></div>`).join('')}</div></section><section class="card"><div class="cardhead"><h2>议价目标情景</h2><span class="badge">测算，不计实际降本</span></div><div class="cardbody"><div class="costrow"><span>统一基准价</span><strong>¥0.46 / 米</strong></div><div class="costrow"><span>示例目标价</span><strong>¥0.43 / 米</strong></div><div class="costrow"><span>可聚合计划量</span><strong>140,000 米</strong></div><div class="costrow total"><span>目标价差 × 计划量</span><strong>¥4,200</strong></div><p class="smalltext">达成价格、交付条件与实际采购量仍需确认；本项只用于说明集中议价的测算方式。</p></div></section></div>`}
function costCalc(c=state.cost){let inputKg=c.weight/1000*(1+c.loss/100),material=c.index/1000*inputKg,base=c.base/1000*inputKg;return {inputKg,material,base,unit:material+c.process+c.other,baseUnit:base+c.process+c.other,delta:(material-base)*c.qty,kg:inputKg*c.qty};}
function costPage(){let c=state.cost,r=costCalc();return `${window.MP?MP.renderPanel():''}<div class="hero"><div class="heroleft"><div class="heroicon">${icon('trend',22)}</div><div><h2>铜价每变化 ¥1,000 / 吨，这包需求的材料成本变化 ¥${money(r.kg,2)}</h2><p>采购投入铜量 ${money(r.kg,2)} 千克，按净铜重与工艺附加损耗计算。全部参数可调整。</p></div></div><span class="pill">成本情景 · 非行情预测</span></div><div class="twocol"><section class="card"><div class="cardhead"><div><h2>线材成本拆分模型</h2><p>22AWG 红线 · 单位：米 · 人民币成本情景 · 原料取价条件需核定</p></div>${icon('box')}</div><div class="cardbody"><div class="formgrid">${field('计划需求量（米）','cost-qty','number',c.qty,'min="1" step="1000"')}${field('净铜重（克 / 米）','cost-weight','number',c.weight,'min="0.01" step="0.1"')}${field('附加损耗（%）','cost-loss','number',c.loss,'min="0" max="50" step="0.1"')}${field('基准铜价（元 / 吨）','cost-base','number',c.base,'min="1" step="1000"')}${field('加工费（元 / 米）','cost-process','number',c.process,'min="0" step="0.01"')}${field('其他费用（元 / 米）','cost-other','number',c.other,'min="0" step="0.01"')}</div><div class="sliderhead"><span>情景铜价（元 / 吨）</span><strong id="cost-index-value">¥${money(c.index,2)}</strong></div><input id="cost-index" aria-label="情景铜价" type="range" min="30000" max="200000" step="0.01" value="${c.index}"><div class="chartfoot"><span>¥30,000 / 吨</span><span>¥200,000 / 吨</span></div><div class="sectiongap">${btn('更新成本测算','recalc-cost',true)} ${btn('生成价格复核任务','create-cost-task')}</div><div class="notice">重量来源、回收料处理和损耗口径均须实际核定。本例采用“净重 ×（1 + 附加损耗率）”，不等同于“净重 ÷ 良率”。</div></div></section><section class="card"><div class="cardhead"><div><h2>成本影响测算</h2><p>随参数更新，可追溯计算过程</p></div><span class="badge">规则计算</span></div><div class="cardbody" id="cost-result">${costResult()}</div></section></div><section class="card sectiongap"><div class="cardhead"><h2>建议下一步</h2><span class="badge">基于规则生成</span></div><div class="cardbody"><div class="helpstep"><span class="num">1</span><div><strong>先核实材料价格与实际投入量</strong><p>情景价格需与约定牌号、地区、税费和取价周期对应。通用参考价需先与供应商的实际结算口径核对。</p></div></div><div class="helpstep"><span class="num">2</span><div><strong>再检查价格联动约定</strong><p>明确基准、免调区间、调整窗口与双向计算规则，生成需采购复核的任务。</p></div></div><div class="helpstep"><span class="num">3</span><div><strong>结合需求讨论锁价与备料</strong><p>还需核验库存、交期、现金占用和订单确定性，演示不自动执行采购或金融交易。</p></div></div></div></section>`}
function costResult(){let c=state.cost,r=costCalc();return `${c.reference?'<div class="notice neutral">取价：'+esc(c.reference.source)+' · '+esc(c.reference.date)+'<br>公开铜现货参考 ¥'+money(c.reference.price,2)+' / 吨；税费、运费条件未知，其他参数仍为演示值。</div>':'<div class="smalltext">手动情景铜价 · 其他参数为演示值</div>'}<div class="smalltext">情景测算单价</div><div class="metricbig">¥${money(r.unit,4)} <small>/ 米</small></div><div class="costrow"><span>铜材料费</span><strong>¥${money(r.material,4)} / 米</strong></div><div class="costrow"><span>加工费</span><strong>¥${money(c.process,4)} / 米</strong></div><div class="costrow"><span>其他费用（绝缘料、包运等）</span><strong>¥${money(c.other,4)} / 米</strong></div><div class="costrow"><span>基准情景单价</span><strong>¥${money(r.baseUnit,4)} / 米</strong></div><div class="costrow total"><span>整包成本变化</span><strong style="color:${r.delta>=0?'#b68542':'#54865c'}">${r.delta>=0?'+':'−'}¥${money(Math.abs(r.delta),2)}</strong></div><p class="smalltext">投入铜量 = ${c.qty} 米 × ${c.weight} 克 / 米 ÷ 1,000 ×（1 + ${c.loss}%）= ${money(r.kg,2)} 千克。<br>成本变化 =（情景铜价 − 基准铜价）÷ 1,000 × 投入铜量。</p>`}
function rankedQuotes(){let w=state.weights,sum=w.price+w.quality+w.delivery;if(sum<=0)return [];let valid=state.quotes.filter(q=>q.currency==='CNY'&&q.freight==='是'&&q.unit==='米'&&q.spec==='22AWG UL1015 红线'&&Number.isFinite(q.tax)&&q.price>0&&q.lead>0),minPrice=Math.min(...valid.map(q=>q.price/(1+q.tax/100)));return state.quotes.map(q=>{let s=suppliers.find(s=>s.name===q.supplier),comparable=valid.includes(q),quality=s?.quality??null;let priceScore=comparable?minPrice/(q.price/(1+q.tax/100))*100:null,deliveryScore=Math.max(0,100-Math.max(0,q.lead-7)*3);return {...q,quality,score:comparable&&quality!==null?(priceScore*w.price+quality*w.quality+deliveryScore*w.delivery)/sum:null};}).sort((a,b)=>(b.score??-1)-(a.score??-1));}
function quotesPage(){let rows=rankedQuotes();return `<div class="twocol"><section class="card"><div class="cardhead"><div><h2>报价结构化导入</h2><p>粘贴或上传标准 CSV · 浏览器规则解析，无外部 AI 调用</p></div>${icon('file')}</div><div class="cardbody"><textarea id="quote-input" class="quotearea" aria-label="报价 CSV 文本" spellcheck="false">${esc(quoteText)}</textarea><div class="actions" style="justify-content:space-between;margin-top:12px"><label class="btn filelabel">${icon('download',13)} 上传 CSV<input id="quote-file" type="file" accept=".csv,text/csv"></label>${btn('解析并核对字段 '+icon('arrow',13),'parse-quotes',true)}</div><div class="smalltext" style="margin-top:11px">不支持直接解析 PDF、Word、图片或真实邮箱；自由格式邮件解析待后续接入。</div></div></section><section class="card"><div class="cardhead"><div><h2>评标权重</h2><p>可调整并重新计算，评分过程公开</p></div><span class="badge">示例规则</span></div><div class="cardbody"><div class="formgrid">${field('价格权重（%）','weight-price','number',state.weights.price,'min="0" max="100"')}${field('品质权重（%）','weight-quality','number',state.weights.quality,'min="0" max="100"')}${field('交期权重（%）','weight-delivery','number',state.weights.delivery,'min="0" max="100"')}</div><div class="sectiongap">${btn('更新评标权重','update-weights')}</div><p class="smalltext">价格分 = 最低可比未税价 ÷ 本报价未税价 × 100；品质分取样例供应商档案；交期分从 7 天起每延长 1 天扣 3 分。权重按合计归一化。</p><div class="notice neutral">不同币种、单位、规格或运费条件，以及缺少税率或供应商评分的报价，保留为待确认，不自动排名。</div></div></section></div><section class="card sectiongap"><div class="cardhead"><div><h2>供应商报价对比</h2><p>统一规格：22AWG UL1015 红线 · 采购条件以各条记录为准</p></div>${btn(icon('download',12)+' 导出对比 CSV','export-quotes')}</div>${rows.length?`<div class="tablewrap"><table><thead><tr><th>供应商</th><th>含税单价</th><th>未税单价</th><th>税率 / 运费</th><th>交期</th><th>综合得分</th><th>状态</th><th></th></tr></thead><tbody>${rows.map((q,i)=>`<tr><td>${esc(q.supplier)}<small>${esc(q.sku)} · ${esc(q.currency)} · ${esc(q.unit)}</small></td><td>${esc(q.currency)} ${money(q.price,4)}</td><td>${Number.isFinite(q.tax)?money(q.price/(1+q.tax/100),4):'待确认'}</td><td>${Number.isFinite(q.tax)?q.tax+'%':'缺失'} / ${q.freight==='是'?'含运':q.freight==='否'?'不含运':'待确认'}</td><td>${q.lead} 天</td><td>${q.score===null?'—':`<span class="scorebar"><span style="width:${q.score}%"></span></span>${q.score.toFixed(1)}`}</td><td>${q.score===null?status('条件待确认','orange'):i===0?status('综合优先候选'):status('备选','gray')}</td><td><button class="rowaction" data-quote="${q.id}">生成申请草稿 →</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">先解析上方两份样例报价，核对字段后即可生成对比结果。</div>'}</section><section class="card sectiongap"><div class="cardhead"><div><h2>价格申请草稿</h2><p>采购确认后的本地记录；未写入 OA 或 ERP</p></div><span class="badge">${state.quoteDrafts.length} 份</span></div>${state.quoteDrafts.length?`<div class="tablewrap"><table><thead><tr><th>草稿编号</th><th>料号 / 供应商</th><th>价格</th><th>状态</th><th></th></tr></thead><tbody>${state.quoteDrafts.map(d=>`<tr><td>${d.id}</td><td>${esc(d.sku)}<small>${esc(d.supplier)}</small></td><td>${money(d.price,4)} ${esc(d.currency)} / ${esc(d.unit)}</td><td>${status('本地待审批草稿','blue')}</td><td><button class="rowaction" data-export-draft="${d.id}">导出 CSV →</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">选择一条已核对报价，模拟生成价格申请草稿。</div>'}</section>`}
function supplierScore(s){let w=state.scoreWeights;return (s.quality*w.quality+s.delivery*w.delivery+s.service*w.service)/(w.quality+w.delivery+w.service)}
function suppliersPage(){return `<div class="hero"><div class="heroleft"><div class="heroicon">${icon('users',22)}</div><div><h2>让供应商评价，成为可解释的选择依据</h2><p>当前演示使用固定评分快照。真实应用需由质量、物管和采购共同维护原始记录。</p></div></div><span class="pill">4 家虚构供应商</span></div><section class="card" style="margin-bottom:20px"><div class="filterbar">${field('品质权重（%）','score-quality','number',state.scoreWeights.quality,'min="0" max="100"')}${field('交付权重（%）','score-delivery','number',state.scoreWeights.delivery,'min="0" max="100"')}${field('协同权重（%）','score-service','number',state.scoreWeights.service,'min="0" max="100"')}${btn('重算绩效评分','update-score-weights')}<span class="smalltext">综合分按权重合计归一化；此处不混入报价竞争力</span></div></section><div class="twocol">${[...suppliers].sort((a,b)=>supplierScore(b)-supplierScore(a)).map(s=>`<section class="card suppliercard"><div class="supplierhero"><div class="avatar">${s.initial}</div><div><h3>${s.name}</h3><small>${s.category} · ${s.note}</small></div><span class="badge" style="margin-left:auto">${s.tier}</span></div><div style="display:flex;justify-content:space-between;align-items:center"><span class="smalltext">综合绩效分</span><span class="metricbig" style="margin:0">${supplierScore(s).toFixed(1)}<small> / 100</small></span></div>${[['品质',s.quality],['交付',s.delivery],['协同',s.service]].map(([l,v])=>`<div class="costrow"><span>${l}评分</span><span><span class="scorebar"><span style="width:${v}%"></span></span>${v}</span></div>`).join('')}<div class="costrow"><span>${s.cert} 模拟证书</span><strong>${s.expiry}</strong></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:17px">${s.id==='S02'?status('28 天后到期','orange'):status('有效期内（模拟）')}<button class="link" data-supplier="${s.id}">查看供应商档案 ${icon('arrow',12)}</button></div></section>`).join('')}</div><div class="notice">工商、诉讼、舆情及财务风险接口尚未接入；不生成无数据依据的财务健康度评分。供应商退出、份额分配与替代均需保供及技术评审。</div>`}
function tasksPage(){let done=state.tasks.filter(t=>t.status==='done'),priceTasks=done.filter(t=>t.finalPrice&&t.actualQty);let savings=priceTasks.reduce((a,t)=>a+(t.baseline-t.finalPrice)*t.actualQty,0);return `<div class="stats">${stat('待处理',state.tasks.filter(t=>t.status==='todo').length,'项','待人工核验或采购启动','task')}${stat('进行中',state.tasks.filter(t=>t.status==='progress').length,'项','已启动，等待结果回填','clock')}${stat('已完成',done.length,'项','本浏览器演示记录','check')}${stat('模拟已确认价差',money(savings,2),'元','仅按演示回填量价计算，非真实降本','coin')}</div><div class="threecol">${[['todo','待处理'],['progress','进行中'],['done','已完成']].map(([k,l])=>`<section class="boardcol"><div class="kanbantitle">${l}<span>${state.tasks.filter(t=>t.status===k).length}</span></div>${state.tasks.filter(t=>t.status===k).map(t=>`<article class="taskcard"><span class="badge">${esc(t.category)}</span><h3>${esc(t.title)}</h3><p>${esc(t.note)}</p>${t.qty?`<p>计划量 ${money(t.qty)} ${esc(t.unit)} · 基准 ¥${money(t.baseline,2)}</p>`:''}${t.status==='done'?`<p class="positive">${t.finalPrice?'回填成交价 ¥'+money(t.finalPrice,4)+' / '+esc(t.unit):'结果已回填'}</p>`:''}<div class="taskmeta"><span>${esc(t.owner)}</span><span>${esc(t.due)}</span></div><button class="rowaction" style="margin-top:12px" data-task="${t.id}">${t.status==='done'?'查看结果':'处理并回填'} →</button></article>`).join('')||'<div class="empty">暂无任务</div>'}</section>`).join('')}</div><div class="notice neutral">任务保存在当前浏览器，可刷新保留。研发确认和审批均为演示角色操作，没有真实身份权限、通知发送或服务端审计。</div>`}
const tourSteps=[{page:'selection',title:'1 / 5 · 输入需求，匹配现有物料',text:'点击“22AWG UL 105℃ 红线”示例，再查看并模拟研发确认。'},{page:'quotes',title:'2 / 5 · 核对报价并比较供应商',text:'解析两份样例报价，调整评分权重，生成价格申请草稿。'},{page:'demand',title:'3 / 5 · 把分散需求集中起来',text:'研发确认三个候选料号可归并，再生成集中议价任务。'},{page:'cost',title:'4 / 5 · 看见行情变化的成本影响',text:'拖动铜价，调整用量和重量，计算成本变化。'},{page:'tasks',title:'5 / 5 · 回填议价结果，形成闭环',text:'打开集中议价任务，启动后回填结果价与模拟实际采购量。'}];
function tourBar(){let t=tourSteps[state.tour-1];return `<div class="tourbar">${icon('spark',17)}<div><strong>${t.title}</strong><div style="margin-top:4px">${t.text}</div></div>${btn(state.tour===5?'结束演示':'下一步 →','tour-next')}<button aria-label="退出引导" data-action="tour-exit">×</button></div>`}
function modal(title,body,footer=''){let focus=document.activeElement;window.modalFocus=focus;$('#overlay').innerHTML=`<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modalhead"><h2 id="modal-title">${title}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><div class="modalbody">${body}</div>${footer?`<div class="modalfoot">${footer}</div>`:''}</section></div>`;bind($('#overlay'));$('#overlay .modal').focus();}
function closeModal(){$('#overlay').innerHTML='';window.modalFocus?.focus();}
function showGuide(){modal('用 5 步，走完一次采购协同',`<p class="sub">建议从电线品类开始。每一步都可以实际点击、修改参数并保存结果。</p>${tourSteps.map((t,i)=>`<div class="helpstep"><span class="num">${i+1}</span><div><strong>${t.title.split('·')[1]}</strong><p>${t.text}</p></div></div>`).join('')}<div class="notice neutral">所有金额、公司、产品、证书和行情均为虚构示例。刷新可保留演示记录，“重置演示”恢复初始状态。</div>`,btn('开始演示 '+icon('arrow',14),'tour-start',true));}
function showAbout(){modal('数据与能力说明',`<div class="helpstep"><span class="num">1</span><div><strong>已实现的演示能力</strong><p>结构化物料筛选、关键词识别、标准 CSV 报价解析、可比条件判断、加权评分、成本公式计算、人工确认、任务回填和 CSV 导出。</p></div></div><div class="helpstep"><span class="num">2</span><div><strong>数据来源与保存</strong><p>需求逻辑来自本次采购访谈及两份采购管理材料。业务区为虚构样例，未上传原始文档、真实供应商资料或采购记录。行情区为公开来源的真实采集记录，在线页展示发布快照，本机后台可按需更新。数据保存在当前浏览器 localStorage，清除浏览器数据将丢失记录。</p></div></div><div class="helpstep"><span class="num">3</span><div><strong>尚未连接的系统</strong><p>连接设置提供本机 IMAP 只读邮箱与 DeepSeek API 配置、测试和报价文本提取，需要自行填写账号参数并实测。OA、ERP、企业微信、交易所逐笔实时行情和工商风险接口尚未接入；公开市场参考价与期货日线已接入；演示区的 CSV 比价仍使用规则计算。</p></div></div><div class="helpstep"><span class="num">4</span><div><strong>正式应用的前置条件</strong><p>需要真实物料与供应商主数据、经核验的重量和成本参数、业务审批规则、系统权限和服务端持久化。演示角色确认不代表真实研发批准。</p></div></div>`,btn('我了解了','close',true));}
function materialModal(id){let m=materials.find(m=>m.id===id),s=supplier(m.supplier);state.selected=id;persist();modal('核对物料与选型依据',`<div class="supplierhero"><div class="avatar">${icon('box',23)}</div><div><h3>${m.name}</h3><small>${m.id} · ${s.name}</small></div></div><div class="costrow"><span>关键参数</span><strong>${esc(m.feature)}</strong></div><p class="smalltext">${m.description}</p><div class="costrow"><span>报价 / 交期</span><strong>¥${money(m.price,2)} / ${m.unit} · ${m.lead} 天</strong></div><div class="costrow"><span>比较条件</span><strong>CNY · 税率 13% · 含运费</strong></div><div class="notice">请以研发角色演示核验完整规格、图纸和认证范围。系统匹配结果不构成自动替代结论。</div><label class="checklabel"><input type="checkbox" id="review-check"><span>已在本次演示中核对关键功能、尺寸、电气参数及认证范围，同意将该样例作为候选选型。</span></label>`,btn('返回','close')+btn(state.reviewed.includes(id)?'再次确认候选':'确认候选选型','confirm-material',true,`data-id="${id}"`));}
function approveDemandModal(){modal('研发确认归并 · 演示操作',`<p class="sub">将 WL-2201、WL-2208、WL-2215 纳入同一需求包。保留原料号，不删除或改写主数据。</p><div class="costrow"><span>聚合规格</span><strong>22AWG UL1015 红线</strong></div><div class="costrow"><span>计划需求</span><strong>140,000 米 · 2026 年 11 月</strong></div><label class="checklabel"><input type="checkbox" id="approve-check"><span>作为演示研发角色，已核对完整规格、认证、颜色和装配要求，确认三个示例需求可以统一采购。</span></label><div class="notice">真实业务需有权限的研发人员签核，并保留图纸版本、验证记录与批准人。</div>`,btn('取消','close')+btn('确认可归并','confirm-demand',true));}
function taskModal(id){let t=state.tasks.find(t=>t.id===id);if(!t)return;let isPrice=Number.isFinite(t.baseline);modal(t.title,`<div class="chips"><span class="chip">${t.id}</span><span class="chip">${esc(t.category)}</span>${taskStatus(t)}</div><p class="sub" style="margin-top:15px">${esc(t.note)}</p><div class="costrow"><span>负责人</span><strong>${esc(t.owner)}</strong></div><div class="costrow"><span>期望完成</span><strong>${esc(t.due)}</strong></div>${isPrice?`<div class="costrow"><span>基准 / 计划量</span><strong>¥${money(t.baseline,4)} / ${esc(t.unit)} × ${money(t.qty)} ${esc(t.unit)}</strong></div>`:''}${t.status==='done'?`<div class="notice neutral">结果：${esc(t.result)}${isPrice?`<br>回填价格 ¥${money(t.finalPrice,4)} / ${esc(t.unit)}；模拟实际量 ${money(t.actualQty)} ${esc(t.unit)}；价差测算 ¥${money((t.baseline-t.finalPrice)*t.actualQty,2)}`:''}<br>演示操作时间：${esc(t.completedAt||'—')}</div>`:`${t.status==='todo'?`<div class="notice">${isPrice&&!state.demandApproved&&!t.confirmed?'先完成需求归并确认后，才能启动集中议价。':'启动后可回填结果；本操作不会发送邮件或通知。'}</div>`:`<div class="formgrid">${isPrice?field('达成含税含运价（元 / '+esc(t.unit)+'）','task-price','number',t.target||t.baseline,'min="0.0001" step="0.0001"')+field('模拟实际采购量（'+esc(t.unit)+'）','task-actual','number',t.qty,'min="1" max="'+t.qty+'" step="1"'):''}</div><label class="field" style="margin-top:16px">跟进结果<textarea id="task-result" placeholder="记录谈判条件、核验结果或后续安排"></textarea></label>${isPrice?'<label class="checklabel"><input type="checkbox" id="task-terms"><span>确认本次价差比较的规格、税率、运费、币种、付款和交付条件一致；回填数量为演示实际量。</span></label>':''}`}`}`,btn('关闭','close')+(t.status==='todo'?btn('启动任务','start-task',true,`data-id="${id}"`):t.status==='progress'?btn('保存结果并完成','complete-task',true,`data-id="${id}"`):''));}
function supplierModal(id){let s=supplier(id);modal(s.name+' · 供应商档案',`<div class="costrow"><span>分层 / 品类</span><strong>${s.tier} · ${s.category}</strong></div><div class="costrow"><span>绩效更新时间</span><strong>2026-10-21（模拟快照）</strong></div><div class="costrow"><span>资质到期</span><strong>${s.expiry}</strong></div><div class="costrow"><span>模具与退出记录</span><strong>尚无演示记录</strong></div><div class="notice neutral">评分 = 品质 ${s.quality} × 权重 + 交付 ${s.delivery} × 权重 + 协同 ${s.service} × 权重，再除以权重之和。实际分数需回溯至质量批次、交付记录和评分依据。</div><h3 style="font-size:12px;margin-top:22px">关联物料</h3><div class="chips">${materials.filter(m=>m.supplier===id).map(m=>`<span class="chip">${m.id} · ${m.name}</span>`).join('')}</div>`,btn('关闭','close')+(s.id==='S02'?btn('查看资质跟进任务','cert-task',true):''));}
function parseCSV(text){let rows=[],row=[],cell='',quoted=false;const t=text.replace(/^\uFEFF/,'');for(let i=0;i<t.length;i++){let ch=t[i];if(ch==='"'){if(quoted&&t[i+1]==='"'){cell+='"';i++;}else if(!quoted&&cell.trim()!==''){throw Error('CSV 引号位置有误，请使用标准 CSV。');}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell.trim());cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&t[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=ch;}if(quoted)throw Error('CSV 存在未闭合的双引号。');row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows;}
function parseQuotes(text){let data=parseCSV(text);if(data.length<2)throw Error('至少需要表头与一条报价。');let required=['供应商','料号','规格','含税单价','税率','交期天','单位','含运费','币种'],header=data[0],missing=required.filter(h=>!header.includes(h));if(missing.length)throw Error('缺少列：'+missing.join('、'));if(new Set(header).size!==header.length)throw Error('表头不能有重名列。');if(data.length>201)throw Error('演示最多支持 200 条报价。');return data.slice(1).map((row,i)=>{if(row.length!==header.length)throw Error('第 '+(i+2)+' 行列数与表头不一致。');let at=h=>row[header.indexOf(h)]?.trim()??'',price=Number(at('含税单价')),lead=Number(at('交期天')),taxText=at('税率'),tax=taxText===''?NaN:Number(taxText.replace('%',''));if(!at('供应商')||!at('料号')||!at('规格')||!at('单位')||!at('币种'))throw Error('第 '+(i+2)+' 行缺少供应商、料号、规格、单位或币种。');if(!Number.isFinite(price)||price<=0||!Number.isFinite(lead)||lead<=0)throw Error('第 '+(i+2)+' 行单价和交期必须大于零。');if(taxText&&(!Number.isFinite(tax)||tax<0||tax>100))throw Error('第 '+(i+2)+' 行税率格式无效，请使用 13% 等百分数。');if(!['','是','否'].includes(at('含运费')))throw Error('含运费列请填“是”“否”或留空。');return {id:'Q-'+String(i+1).padStart(3,'0'),supplier:at('供应商'),sku:at('料号'),spec:at('规格'),price,tax,lead,unit:at('单位'),freight:at('含运费'),currency:at('币种').toUpperCase()};});}
let pendingQuotes=[];
function parseQuoteModal(){quoteText=$('#quote-input').value;try{pendingQuotes=parseQuotes(quoteText);modal('核对解析字段',`<p class="sub">识别到 ${pendingQuotes.length} 条报价。导入后按可比条件评分，缺失条件保留为待确认。</p><div class="tablewrap compact"><table><thead><tr><th>供应商 / 料号</th><th>含税单价</th><th>税率 / 运费</th><th>交期</th></tr></thead><tbody>${pendingQuotes.map(q=>`<tr><td>${esc(q.supplier)}<small>${esc(q.sku)} · ${esc(q.spec)}</small></td><td>${money(q.price,4)} ${esc(q.currency)} / ${esc(q.unit)}</td><td>${Number.isFinite(q.tax)?q.tax+'%':'待确认'} / ${q.freight==='是'?'含运费':q.freight==='否'?'不含运费':'待确认'}</td><td>${q.lead} 天</td></tr>`).join('')}</tbody></table></div><label class="checklabel"><input type="checkbox" id="quote-check"><span>已核对样例报价的供应商、料号、规格、价格及比较条件。继续将替换当前报价对比数据，已保存草稿保留。</span></label>`,btn('返回修改','close')+btn('确认导入对比','confirm-quotes',true));}catch(e){toast(e.message);}}
function quoteDraftModal(id){let q=state.quotes.find(q=>q.id===id);if(!q)return;modal('生成价格申请草稿',`<div class="formgrid">${field('供应商','draft-supplier','text',q.supplier)}${field('内部料号','draft-sku','text',q.sku)}${field('含税单价','draft-price','number',q.price,'min="0.0001" step="0.0001"')}${field('税率（百分数）','draft-tax','number',q.tax??'','min="0" max="100"')}${field('币种','draft-currency','text',q.currency)}${field('计量单位','draft-unit','text',q.unit)}</div><label class="field" style="margin-top:12px">规格<input id="draft-spec" value="${esc(q.spec)}"></label><label class="checklabel"><input type="checkbox" id="draft-check"><span>已核对报价及税运条件，仅生成本地演示草稿，未向 OA 提交审批。</span></label><div class="notice">含运费：${q.freight==='是'?'是':q.freight==='否'?'否':'待确认'}；真实价格申请需补充报价有效期、附件、付款条件和审批链。</div>`,btn('取消','close')+btn('保存本地草稿','save-draft',true,`data-id="${id}"`));}
function exportCSV(name,headers,rows,message='已导出 CSV，业务区为演示记录。'){const cell=v=>{let t=String(v??'');if(/^[\s]*[=+@-]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';};const body='\uFEFF'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([body],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(message);}
function matchQuery(query){let q=query.trim().toUpperCase(),f={awg:'',cert:'',temp:'',pitch:'',grade:''};if(!q){toast('请输入需求，或使用下方示例。');return;}if(/端子|连接器|针距/.test(q))state.category='terminal';else if(/粒子|塑料|PC|V-0|V-2/.test(q))state.category='resin';else if(/线|AWG/.test(q))state.category='wire';let awg=q.match(/(\d{1,2})\s*AWG/);if(awg)f.awg=awg[1]+'AWG';if(/UL/.test(q))f.cert='UL';if(/CQC/.test(q))f.cert='CQC';let temp=q.match(/(\d{2,3})\s*[℃°度]/);if(temp)f.temp=temp[1];let pitch=q.match(/(\d+(?:\.\d+)?)\s*MM/);if(pitch)f.pitch=Number(pitch[1]).toFixed(1)+'mm';let grade=q.match(/V-?([012])/);if(grade)f.grade='V-'+grade[1];let style=q.match(/UL(\d{4})/);if(style)f.style='UL'+style[1];if(/硅胶/.test(q))f.style='硅胶';if(/抗UV/.test(q))f.uv='抗UV';if(/按压/.test(q))f.function='按压式';if(/螺钉/.test(q))f.function='螺钉式';let voltage=q.match(/(\d{2,4})\s*V\b/);if(voltage)f.voltage=voltage[1]+'V';if(/红/.test(q))f.color='红色';if(/黑/.test(q))f.color='黑色';state.filters=f;state.query=query;persist();render();toast('已按可识别关键词筛选，请继续核对完整技术要求。');}
const originalFiltered=filteredMaterials;
filteredMaterials=function(){let f=state.filters;return originalFiltered().filter(m=>(!f.style||m.name.includes(f.style))&&(!f.uv||m.uv===f.uv)&&(!f.function||m.feature.includes(f.function))&&(!f.voltage||m.feature.includes(f.voltage))&&(!f.color||m.feature.includes(f.color)));};
function readCost(){let c={...state.cost};for(let k of ['qty','weight','loss','base','process','other']){let v=$('#cost-'+k).value;if(v.trim()===''||!Number.isFinite(Number(v)))throw Error('请填写完整的有效数字。');c[k]=Number(v);}c.index=Number($('#cost-index').value);if(c.qty<=0||c.weight<=0||c.base<=0||c.loss<0||c.loss>50||c.process<0||c.other<0)throw Error('请检查用量、重量、基准价及损耗范围（0–50%）。');if(c.reference&&c.index!==c.reference.price)delete c.reference;return c;}
function readWeights(prefix,keys){let w={};for(let key of keys){let raw=$('#'+prefix+'-'+key).value,n=Number(raw);if(raw.trim()===''||!Number.isFinite(n)||n<0||n>100)throw Error('每项权重需在 0–100 之间。');w[key]=n;}if(Object.values(w).reduce((a,b)=>a+b,0)<=0)throw Error('权重合计必须大于 0。');return w;}
function go(page){state.page=page;persist();render();window.scrollTo({top:0,behavior:'smooth'});}
function bind(root=document){if(window.MP)MP.bind(root);if(window.PC)PC.bind(root);root.querySelectorAll('[data-portfolio-back]').forEach(el=>el.onclick=e=>{if(e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;let canBack=window.navigation?.canGoBack??(window.history.length>1&&Boolean(document.referrer));if(canBack){e.preventDefault();window.history.back();}});root.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{if(el.dataset.cat){state.category=el.dataset.cat;state.filters=defaults().filters;}go(el.dataset.page);});root.querySelectorAll('[data-category]').forEach(el=>el.onclick=()=>{state.category=el.dataset.category;state.filters=defaults().filters;state.query='';persist();render();});root.querySelectorAll('[data-example]').forEach(el=>el.onclick=()=>matchQuery({wire:'22AWG UL1015 105℃ 红线',terminal:'UL 5.0mm 按压式端子',resin:'PC V-0 抗UV 粒子'}[el.dataset.example]));root.querySelectorAll('[data-task]').forEach(el=>el.onclick=()=>taskModal(el.dataset.task));root.querySelectorAll('[data-supplier]').forEach(el=>el.onclick=()=>supplierModal(el.dataset.supplier));root.querySelectorAll('[data-quote]').forEach(el=>el.onclick=()=>quoteDraftModal(el.dataset.quote));root.querySelectorAll('[data-export-draft]').forEach(el=>el.onclick=()=>{let d=state.quoteDrafts.find(d=>d.id===el.dataset.exportDraft);exportCSV('价格申请草稿-'+d.id+'.csv',['编号','供应商','料号','规格','含税单价','税率','币种','单位','含运费','状态'],[[d.id,d.supplier,d.sku,d.spec,d.price,d.tax+'%',d.currency,d.unit,d.freight,'本地演示草稿']]);});root.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{try{action(el.dataset.action,el);}catch(e){toast(e.message||'操作未完成，请检查输入。');}});root.querySelectorAll('[id^="filter-"]').forEach(el=>el.onchange=()=>{state.filters[el.id.slice(7)]=el.value;persist();render();});let q=root.querySelector('#selection-query');if(q)q.onkeydown=e=>{if(e.key==='Enter')matchQuery(q.value)};let range=root.querySelector('#cost-index');if(range)range.oninput=()=>{try{state.cost=readCost();persist();$('#cost-index-value').textContent='¥'+money(state.cost.index,2);$('#cost-result').innerHTML=costResult();}catch(e){toast(e.message)}};let file=root.querySelector('#quote-file');if(file)file.onchange=async()=>{let f=file.files[0];if(!f)return;if(f.size>1048576){toast('演示 CSV 文件请控制在 1MB 以内。');return;}quoteText=await f.text();$('#quote-input').value=quoteText;toast('CSV 已载入，请点击解析并核对字段。');};}
function action(name,el){switch(name){
case 'menu':$('#sidebar').classList.toggle('open');break;
case 'guide':showGuide();break;
case 'about':showAbout();break;
case 'close':closeModal();break;
case 'go-demand':go('demand');break;
case 'tour-start':state.tour=1;closeModal();go(tourSteps[0].page);break;
case 'tour-next':if(state.tour>=5){state.tour=0;persist();render();toast('演示流程结束，可继续自由体验。');}else{state.tour++;go(tourSteps[state.tour-1].page);}break;
case 'tour-exit':state.tour=0;persist();render();break;
case 'reset':modal('重置演示记录',`<p class="sub">清除当前浏览器保存的选型确认、报价、草稿和任务结果，恢复初始样例数据。</p>`,btn('保留记录','close')+btn('确认重置','confirm-reset',true));break;
case 'confirm-reset':state=defaults();quoteText=sampleQuote;persist();closeModal();render();toast('已恢复初始演示数据。');break;
case 'match':matchQuery($('#selection-query').value);break;
case 'clear-filters':state.filters=defaults().filters;state.query='';persist();render();break;
case 'select-material':materialModal(el.dataset.id);break;
case 'confirm-material':if(!$('#review-check').checked)throw Error('请先勾选核验确认。');if(!state.reviewed.includes(el.dataset.id))state.reviewed.push(el.dataset.id);state.selected=el.dataset.id;persist();closeModal();render();toast('已记录演示选型确认，真实业务仍需正式签核。');break;
case 'approve-demand':approveDemandModal();break;
case 'confirm-demand':if(!$('#approve-check').checked)throw Error('请先勾选研发核验确认。');state.demandApproved=true;persist();closeModal();render();toast('已记录研发归并确认，可生成集中议价任务。');break;
case 'update-threshold':{let v=Number($('#demand-threshold').value);if(!Number.isFinite(v)||v<=0)throw Error('请填写大于 0 的金额门槛。');state.threshold=v;persist();render();toast(totalSpend()>=v?'规则已更新：需求包已达到触发门槛。':'规则已更新：当前金额尚未达到触发门槛。');break;}
case 'create-demand-task':{if(!state.demandApproved)throw Error('请先完成研发归并确认。');if(totalSpend()<state.threshold)throw Error('当前需求金额尚未达到设定门槛。');let old=state.tasks.find(t=>t.source==='demand-202611'||t.source==='demo-wire');if(old){old.confirmed=true;old.source='demand-202611';old.note='研发归并已在演示中确认，11 月三项目共 140,000 米，采购比较基准为含税含运价 ¥0.46 / 米。';persist();go('tasks');toast('已激活现有集中议价任务，保留原任务避免重复创建。');}else{state.tasks.unshift({id:'TASK-'+String(Date.now()).slice(-6),title:'22AWG 红线集中议价',category:'需求聚合',status:'todo',owner:'采购 · 陈宁',due:'2026-10-28',qty:totalQty(),baseline:.46,unit:'米',target:.43,note:'研发归并已确认，需集中询价与议价。',confirmed:true,source:'demand-202611'});persist();go('tasks');toast('集中议价任务已生成。');}break;}
case 'recalc-cost':state.cost=readCost();persist();render();toast('成本情景已更新。');break;
case 'create-cost-task':{state.cost=readCost();let r=costCalc(),key='cost-'+JSON.stringify(state.cost);if(state.tasks.some(t=>t.source===key)){toast('同一成本情景已存在复核任务。');break;}state.tasks.unshift({id:'TASK-'+String(Date.now()).slice(-6),title:'铜价情景变动 · 价格复核',category:'行情成本',status:'todo',owner:'采购 · 陈宁',due:'2026-10-28',note:(state.cost.reference?'公开铜价参考 '+state.cost.reference.source+' '+state.cost.reference.date+'；税费运费待核定，演示用量。¥':'手动情景铜价 ¥')+money(state.cost.index)+' / 吨；相对基准，需求包成本变化 ¥'+money(r.delta,2)+'。请核定真实取价与调价约定。',source:key});persist();go('tasks');toast('已生成成本复核任务。');break;}
case 'parse-quotes':parseQuoteModal();break;
case 'confirm-quotes':if(!$('#quote-check').checked)throw Error('请先勾选报价字段核对确认。');state.quotes=pendingQuotes;persist();closeModal();render();toast('报价已导入，综合排名已按可比条件计算。');break;
case 'update-weights':state.weights=readWeights('weight',['price','quality','delivery']);persist();render();toast('评标权重已更新，排名重新计算。');break;
case 'update-score-weights':state.scoreWeights=readWeights('score',['quality','delivery','service']);persist();render();toast('供应商绩效评分已重算。');break;
case 'export-quotes':{let rows=rankedQuotes();if(!rows.length)throw Error('请先导入报价。');exportCSV('模拟供应商报价对比.csv',['供应商','料号','规格','含税单价','税率','单位','币种','含运费','交期天','综合得分'],rows.map(q=>[q.supplier,q.sku,q.spec,q.price,Number.isFinite(q.tax)?q.tax+'%':'待确认',q.unit,q.currency,q.freight,q.lead,q.score===null?'条件待确认':q.score.toFixed(2)]));break;}
case 'save-draft':{if(!$('#draft-check').checked)throw Error('请先勾选草稿核对确认。');let q=state.quotes.find(q=>q.id===el.dataset.id),d={...q};for(let k of ['supplier','sku','spec','currency','unit']){d[k]=$('#draft-'+k).value.trim();if(!d[k])throw Error('请补全所有草稿字段。');}d.price=Number($('#draft-price').value);d.tax=Number($('#draft-tax').value);if(!$('#draft-tax').value.trim()||!Number.isFinite(d.price)||d.price<=0||!Number.isFinite(d.tax)||d.tax<0||d.tax>100)throw Error('请填写有效价格与税率，未知税率不能按零处理。');if(!['是','否'].includes(d.freight))throw Error('运费条件未确认，请返回 CSV 补全后重导。');d.id='DRAFT-'+String(Date.now()).slice(-7);state.quoteDrafts.unshift(d);persist();closeModal();render();toast('价格申请草稿已保存，未向 OA 提交。');break;}
case 'cert-task':closeModal();taskModal('TASK-002');break;
case 'start-task':{let t=state.tasks.find(t=>t.id===el.dataset.id);if(t.baseline&&!t.confirmed&&!state.demandApproved)throw Error('请先在需求聚合页面完成研发归并确认。');t.status='progress';persist();closeModal();render();taskModal(t.id);toast('任务已启动，可回填跟进结果。');break;}
case 'complete-task':{let t=state.tasks.find(t=>t.id===el.dataset.id),result=$('#task-result').value.trim();if(result.length<4)throw Error('请填写至少 4 个字的跟进结果。');if(t.baseline){let price=Number($('#task-price').value),qty=Number($('#task-actual').value);if(!Number.isFinite(price)||price<=0||!Number.isFinite(qty)||qty<=0||qty>t.qty)throw Error('请填写有效价格，实际量须大于 0 且不超过计划量。');if(!$('#task-terms').checked)throw Error('请先确认价差比较条件一致。');t.finalPrice=price;t.actualQty=qty;}t.result=result;t.status='done';t.completedAt=new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});persist();closeModal();render();toast('跟进结果已保存，任务完成。');break;}
}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#overlay').children.length)closeModal();if(e.key==='Tab'&&$('#overlay').children.length){let els=$$('#overlay button, #overlay input, #overlay select, #overlay textarea, #overlay [href]').filter(e=>!e.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('#overlay .modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
render();
